def advance(text, kind, weight, size):
    """Advance width in SVG user units, before SAFETY."""
    w = weight if weight in (400, 500, 700) else (700 if weight >= 600 else 400)
    row = ADVANCE["%s/%d" % (kind, w)]
    fallback = row[110]  # 'n', a reasonable stand-in for anything unmeasured
    return sum(row.get(ord(ch), fallback) for ch in text) * size
